package witchinggadgets;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.gametest.framework.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.crafting.*;
import thaumcraft.research.*;

@GameTestHolder(WitchingGadgets.ID)
@PrefixGameTestTemplate(false)
public final class PortGameTests {
    static MachineEntity place(GameTestHelper h,String kind){BlockPos p=new BlockPos(2,2,2);h.setBlock(p,Content.block(kind));return h.getBlockEntity(p);}
    @GameTest(template="test/platform") public static void allOriginalRecipesResolve(GameTestHelper h){
        int count=0;List<String> missing=new ArrayList<>();
        for(TcRecipe recipe:TcRecipes.all())if(recipe.key().startsWith("WG:")){
            count++;var ingredients=recipe instanceof ShapedArcaneRecipe r?r.grid():recipe instanceof ShapelessArcaneRecipe r?r.ingredients():recipe instanceof InfusionRecipe r?java.util.stream.Stream.concat(java.util.stream.Stream.of(r.central()),r.components().stream()).toList():recipe instanceof InfusionEnchantmentRecipe r?r.components():recipe instanceof CrucibleRecipe r?List.of(r.catalyst()):List.<TcIngredient>of();
            for(var i:ingredients)if(!i.exists())missing.add(recipe.key()+" ingredient "+i);
            var result=recipe instanceof ShapedArcaneRecipe r?r.result():recipe instanceof ShapelessArcaneRecipe r?r.result():recipe instanceof InfusionRecipe r?r.result():recipe instanceof CrucibleRecipe r?r.result():recipe instanceof CraftingRecipeRef r?r.result():null;
            if(result!=null&&!result.exists())missing.add(recipe.key()+" result "+result);
        }
        h.assertTrue(count>=65,"expected original recipes, got "+count);h.assertTrue(missing.isEmpty(),String.join("; ",missing));h.succeed();
    }
    @GameTest(template="test/platform") public static void researchDependenciesResolve(GameTestHelper h){List<String> missing=new ArrayList<>();var cat=ResearchCategories.get(Research.CATEGORY);h.assertTrue(cat!=null,"category missing");for(var e:cat.research()){for(String p:e.parents())if(ResearchCategories.getResearch(p)==null)missing.add(e.key()+" -> "+p);for(String p:e.parentsHidden())if(ResearchCategories.getResearch(p)==null)missing.add(e.key()+" -> "+p);}h.assertTrue(missing.isEmpty(),String.join("; ",missing));h.succeed();}
    @GameTest(template="test/platform") public static void ravenContentTracksTwilightForest(GameTestHelper h){boolean recipe=TcRecipes.get("WG:CLOAK_RAVEN")!=null;h.assertTrue(recipe==Compat.twilight(),"raven recipe must follow optional Twilight Forest");h.assertTrue((ResearchCategories.getResearch("CLOAK_RAVEN")!=null)==Compat.twilight(),"raven research mismatch");h.succeed();}
    @GameTest(template="test/platform") public static void spinningWheelUsesFourInputsAndProducesTwoYarn(GameTestHelper h){var m=place(h,"spinning_wheel");for(int i=0;i<4;i++)m.items.setStackInSlot(i,new ItemStack(Items.STRING));for(int i=0;i<121;i++)m.spin();h.assertTrue(m.items.getStackInSlot(5).is(Content.item("yarn")),"yarn output missing");h.assertValueEqual(m.items.getStackInSlot(5).getCount(),2,"wrong yield");for(int i=0;i<4;i++)h.assertTrue(m.items.getStackInSlot(i).isEmpty(),"input not consumed");h.succeed();}
    @GameTest(template="test/platform") public static void spinningWheelRejectsUnrelatedFifthInput(GameTestHelper h){var m=place(h,"spinning_wheel");for(int i=0;i<4;i++)m.items.setStackInSlot(i,new ItemStack(Items.STRING));m.items.setStackInSlot(4,new ItemStack(Items.DIAMOND));for(int i=0;i<130;i++)m.spin();h.assertTrue(m.items.getStackInSlot(5).isEmpty(),"invalid input crafted");h.assertTrue(m.items.getStackInSlot(4).is(Items.DIAMOND),"unrelated input was consumed");h.succeed();}
    @GameTest(template="test/platform") public static void blockedOutputPreservesInputs(GameTestHelper h){var m=place(h,"spinning_wheel");for(int i=0;i<4;i++)m.items.setStackInSlot(i,new ItemStack(Items.STRING));m.items.setStackInSlot(5,new ItemStack(Items.STONE,64));for(int i=0;i<130;i++)m.spin();h.assertValueEqual(m.items.getStackInSlot(0).getCount(),1,"blocked machine consumed inputs");h.succeed();}
    @GameTest(template="test/platform") public static void storageRoundTripAndNestedBagRejection(GameTestHelper h){var sack=Content.stack("bag_of_tricks");var s=new BagItem.Storage(sack,18);s.setItem(0,new ItemStack(Items.DIAMOND,12));var copy=sack.copy();var restored=new BagItem.Storage(copy,18);h.assertValueEqual(restored.getItem(0).getCount(),12,"bag lost components");h.assertTrue(!BagItem.canStore(copy),"nested bag accepted");restored.removeItem(0,5);h.assertValueEqual(new BagItem.Storage(copy,18).getItem(0).getCount(),7,"extraction not persisted");h.assertValueEqual(new BagItem.Storage(sack,18).getItem(0).getCount(),12,"copy mutated original");h.succeed();}
    @GameTest(template="test/platform") public static void cloakHasFiftyPercentExtraStorage(GameTestHelper h){var sack=new BagItem.Storage(Content.stack("bag_of_tricks"),18);var cloak=new BagItem.Storage(Content.stack("cloak_of_voluminous_pockets"),27);h.assertValueEqual(cloak.getContainerSize()*2,sack.getContainerSize()*3,"cloak capacity");h.succeed();}
    @GameTest(template="test/platform") public static void gemAffinitiesAndChargesMatchOriginal(GameTestHelper h){h.assertTrue(GemItem.affinity("diamond",Aspect.ORDER)&&GemItem.affinity("diamond",Aspect.ENTROPY),"diamond affinities");h.assertTrue(GemItem.aversion("emerald",Aspect.WATER),"emerald aversion");h.assertValueEqual(GemItem.cost(Aspect.ENTROPY,1),16,"mirror gem charge");h.assertValueEqual(GemItem.cost(Aspect.ORDER,1),2,"order gem charge");h.assertValueEqual(GemItem.cost(Aspect.FIRE,0),32,"point gem consumed");h.succeed();}
    @GameTest(template="test/platform") public static void pointOrderGemHealsAndIsConsumed(GameTestHelper h){var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);p.setHealth(5);var gem=GemItem.create(Aspect.ORDER,0,0,0);GemItem.activate(gem,p,false);h.assertTrue(gem.isEmpty(),"point gem not consumed");h.assertTrue(p.getHealth()>=11,"order point failed to heal");h.succeed();}
    @GameTest(template="test/platform") public static void gauntletStabilizesPointGems(GameTestHelper h){var p=h.makeMockPlayer(net.minecraft.world.level.GameType.SURVIVAL);p.setHealth(5);var gem=GemItem.create(Aspect.ORDER,0,0,3);GemItem.activate(gem,p,true);h.assertTrue(!gem.isEmpty(),"gauntlet gem shattered");h.assertValueEqual(Data.get(gem).getInt("Spent"),32,"gauntlet charge was not consumed");h.succeed();}
    @GameTest(template="test/platform") public static void saunaWaterLastsTenMinutes(GameTestHelper h){var m=place(h,"sauna_stove");m.water.fill(new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,1000),net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);m.sauna(h.getLevel());h.assertValueEqual(m.water.getFluidAmount(),0,"bucket not consumed");h.assertValueEqual(m.steamTicks,11999,"one bucket must last 12000 game ticks");h.succeed();}
    @GameTest(template="test/platform") public static void machineInventoryAndFluidSurviveReload(GameTestHelper h){var m=place(h,"sauna_stove");m.items.setStackInSlot(3,new ItemStack(Items.EMERALD,7));m.water.fill(new net.neoforged.neoforge.fluids.FluidStack(net.minecraft.world.level.material.Fluids.WATER,2000),net.neoforged.neoforge.fluids.capability.IFluidHandler.FluidAction.EXECUTE);var nbt=m.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new MachineEntity(m.getBlockPos(),m.getBlockState());restored.loadWithComponents(nbt,h.getLevel().registryAccess());h.assertValueEqual(restored.items.getStackInSlot(3).getCount(),7,"inventory reload");h.assertValueEqual(restored.water.getFluidAmount(),2000,"water reload");h.succeed();}
}
